export const getSerialConflictWith = (targetMk: string, selectedList: string[]): string | null => {
  for (const [mkA, mkB] of PASANGAN_MK_BERSERI) {
    if (targetMk === mkA && selectedList.includes(mkB)) {
      return mkB;
    }
    if (targetMk === mkB && selectedList.includes(mkA)) {
      return mkA;
    }
  }
  return null;
};

export const checkAllSerialConflicts = (
  selectedList: string[]
): { mk1: string; mk2: string; pairName: string }[] => {
  const conflicts: { mk1: string; mk2: string; pairName: string }[] = [];
  for (const [mkA, mkB] of PASANGAN_MK_BERSERI) {
    if (selectedList.includes(mkA) && selectedList.includes(mkB)) {
      const nameA = parseMkKonversiString(mkA).nama;
      const nameB = parseMkKonversiString(mkB).nama;
      conflicts.push({
        mk1: mkA,
        mk2: mkB,
        pairName: `${nameA} & ${nameB}`
      });
    }
  }
  return conflicts;
};

export const checkCanSelectMkKonversi = (
  targetMk: string,
  selectedList: string[]
): {
  canSelect: boolean;
  reason?: 'serial' | 'exceed_16' | 'unreachable_target';
  conflictWith?: string;
  projectedTotalSks: number;
  message?: string;
} => {
  const currentTotalSks = selectedList.reduce((sum, item) => sum + extractSksFromMkKonversi(item), 0);
  const targetInfo = parseMkKonversiString(targetMk);
  const projectedTotalSks = currentTotalSks + targetInfo.sks;

  const conflictWith = getSerialConflictWith(targetMk, selectedList);
  if (conflictWith) {
    const conflictInfo = parseMkKonversiString(conflictWith);
    return {
      canSelect: false,
      reason: 'serial',
      conflictWith,
      projectedTotalSks,
      message: `Mata kuliah "${targetInfo.nama}" tidak dapat dipilih bersamaan dengan "${conflictInfo.nama}". Sesuai ketentuan kurikulum KLK, mata kuliah berseri/berurutan (seperti Seri I dan Seri II) tidak boleh diambil berpasangan dalam satu usulan KLK.`
    };
  }

  if (projectedTotalSks > 20) {
    return {
      canSelect: false,
      reason: 'exceed_16',
      projectedTotalSks,
      message: `Tidak dapat memilih "${targetInfo.nama}" (${targetInfo.sks} SKS). Total beban SKS saat ini adalah ${currentTotalSks} SKS. Jika ditambahkan, totalnya menjadi ${projectedTotalSks} SKS (melebihi batas maksimal kombinasi 20 SKS). Pilihan mata kuliah konversi hanya boleh memenuhi target kombinasi 4, 7, 10, 13, 16, atau 20 SKS.`
    };
  }

  const candidateList = [...selectedList, targetMk];
  const hasOneSksCourse = candidateList.some((item) => extractSksFromMkKonversi(item) === 1);
  if (projectedTotalSks === 15 && hasOneSksCourse) {
    return {
      canSelect: false,
      reason: 'unreachable_target',
      projectedTotalSks,
      message: `Tidak dapat memilih "${targetInfo.nama}" (${targetInfo.sks} SKS) karena akan menghasilkan total 15 SKS sementara mata kuliah 1 SKS sudah terpilih, sehingga tidak mungkin mencapai target kombinasi 16 SKS. Pilihan mata kuliah konversi hanya boleh memenuhi target kombinasi 4, 7, 10, 13, atau 16 SKS.`
    };
  }

  return {
    canSelect: true,
    projectedTotalSks
  };
};

