// Helper untuk memeriksa apakah Dosen Pembimbing KLK telah resmi ditetapkan oleh Admin
export const checkIsDosenKLKDitetapkanAdmin = (
  klkItem: PengajuanKLK | null | undefined
): boolean => {
  if (!klkItem) return false;
  if (klkItem.isDosenKLKDitetapkanAdmin === true || klkItem.dosenPembimbingKLKDitetapkan === true) {
    return true;
  }
  // Jika sudah disetujui admin atau sedang berjalan / selesai dinilai
  if (
    klkItem.status === 'Disetujui' ||
    klkItem.status === 'Disetujui / Sedang Berjalan' ||
    klkItem.status === 'Selesai & Dinilai'
  ) {
    return Boolean(klkItem.dosenPembimbingKLK && !klkItem.dosenPembimbingKLK.includes('Belum Ditetapkan'));
  }
  // Cek jika terdapat riwayat aktivitas resmi dari Admin
  if (Array.isArray(klkItem.riwayatAktivitas)) {
    const hasAdminAction = klkItem.riwayatAktivitas.some(
      (r) =>
        (r.role === 'Admin' || r.role === 'Super Admin') &&
        (r.aksi.includes('Dosen Pembimbing KLK') || (r.catatan && r.catatan.includes('Dosen Pembimbing KLK ditetapkan')))
    );
    if (hasAdminAction && klkItem.dosenPembimbingKLK && !klkItem.dosenPembimbingKLK.includes('Belum Ditetapkan')) {
      return true;
    }
  }
  return false;
};

// Helper ketat khusus Logbook Mingguan: HANYA Dosen Pembimbing KLK yang ditetapkan Admin (bukan DPA atau dosen lain)
export const checkIsDosenPembimbingKlkOnly = (
  user: AuthUser | null | undefined,
  klkItem: PengajuanKLK | null | undefined,
  dosenList: Dosen[] = []
): boolean => {
  if (!user || !klkItem) return false;

  const roleStr = String(user.role || '').toLowerCase();
  const isDosenUser =
    roleStr === 'dosen' ||
    Boolean(user.jabatan && user.jabatan.toLowerCase().includes('dosen'));
  if (!isDosenUser) return false;

  const isDosenKLKDitetapkan = checkIsDosenKLKDitetapkanAdmin(klkItem);
  const assignedName = (klkItem.dosenPembimbingKLK || '').trim();
  if (!isDosenKLKDitetapkan || !assignedName || assignedName.includes('Belum Ditetapkan')) {
    return false;
  }

  const normalizeName = (s: string) =>
    s
      .toLowerCase()
      .replace(/prof\.|dr\.|dra\.|ir\.|s\.si\.|m\.si\.|m\.sc\.|ph\.d\.|s\.tp\.|m\.eng\.|sc\.|m\.s\.|s\.t\.|m\.t\.|s\.pd\.|m\.pd\./gi, ' ')
      .replace(/[^a-z0-9\s]/gi, ' ')
      .replace(/\s+/g, ' ')
      .trim();

  const assignedClean = normalizeName(assignedName);
  const userNamaRaw = (user.nama || (user as any).name || '').trim();
  const userClean = normalizeName(userNamaRaw);
  const userUsernameClean = (user.username || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const userIdClean = (user.identifier || '').replace(/\D/g, '');
  const userEmailClean = (user.email || '').toLowerCase().trim();

  // 1. Cocokkan terhadap data master Dosen berdasarkan nama Dosen Pembimbing KLK
  const matchedMasterDosen = dosenList.find((d) => {
    const dClean = normalizeName(d.nama || '');
    return (
      (dClean && assignedClean && dClean === assignedClean) ||
      (d.nama && d.nama.trim().toLowerCase() === assignedName.toLowerCase())
    );
  });
  if (matchedMasterDosen) {
    if (user.id && matchedMasterDosen.id && user.id === matchedMasterDosen.id) return true;
    const dNipClean = (matchedMasterDosen.nip || '').replace(/\D/g, '');
    if (userIdClean && dNipClean && userIdClean === dNipClean) return true;
    const dEmailClean = (matchedMasterDosen.email || '').toLowerCase().trim();
    if (userEmailClean && dEmailClean && userEmailClean === dEmailClean) return true;
  }

  // 2. Cocokkan nama lengkap / panggilan tanpa gelar (seluruh token harus cocok utuh)
  if (userClean && assignedClean) {
    if (userClean === assignedClean) return true;
    const userTokens = userClean.split(/\s+/).filter((t) => t.length >= 2);
    const assignedTokens = assignedClean.split(/\s+/).filter((t) => t.length >= 2);
    if (
      userTokens.length > 0 &&
      assignedTokens.length > 0 &&
      (userTokens.every((t) => assignedTokens.includes(t)) ||
        assignedTokens.every((t) => userTokens.includes(t)))
    ) {
      return true;
    }
  }

  // 3. Cocokkan username terhadap token nama Dosen Pembimbing KLK
  if (userUsernameClean && assignedClean) {
    const assignedNoSpace = assignedClean.replace(/\s+/g, '');
    const assignedTokens = assignedClean.split(/\s+/).filter((t) => t.length >= 3);
    if (
      userUsernameClean === assignedNoSpace ||
      (userUsernameClean.length >= 4 && assignedNoSpace.includes(userUsernameClean)) ||
      assignedTokens.some((t) => t === userUsernameClean)
    ) {
      return true;
    }
  }

  return false;
};

export const checkIsDosenPAForStudent = (
  user: AuthUser | null | undefined,
  klkItem: PengajuanKLK | null | undefined,
  mhsList: Mahasiswa[]
): boolean => {
  if (!user || !klkItem) return false;
  // Super Admin dan Admin berwenang memantau & melakukan supervisi pada seluruh usulan
  if (user.role === 'super_admin' || (user.role as any) === 'superadmin' || user.role === 'admin') {
    return true;
  }

  const student = mhsList.find(
    (m) =>
      m.id === klkItem.mahasiswaId ||
      (klkItem.nim && m.nim && m.nim.replace(/\D/g, '') === klkItem.nim.replace(/\D/g, '')) ||
      (klkItem.mahasiswaNama && m.nama && klkItem.mahasiswaNama.toLowerCase().trim() === m.nama.toLowerCase().trim())
  );

  // Jika Dosen Pembimbing KLK telah ditetapkan atau diganti oleh Admin (dan bukan 'Belum Ditetapkan')
  const isDosenKLKDitetapkan = checkIsDosenKLKDitetapkanAdmin(klkItem);
  const hasCustomAssignedDosen =
    isDosenKLKDitetapkan &&
    Boolean(klkItem.dosenPembimbingKLK) &&
    !klkItem.dosenPembimbingKLK?.includes('Belum Ditetapkan');

  const activeDosenNama = hasCustomAssignedDosen
    ? klkItem.dosenPembimbingKLK!
    : (klkItem.dpaNama || student?.dosenPANama || '');

  if (!activeDosenNama) return false;

  // Jika Dosen Pembimbing KLK BELUM diganti oleh Admin, cek ID & NIP DPA
  if (!hasCustomAssignedDosen) {
    const dpaId = klkItem.dpaId || student?.dosenPAId || '';
    if (dpaId && (user.id === dpaId || (user.identifier && user.identifier === dpaId))) {
      return true;
    }

    const dpaNip = student?.dosenPANip || '';
    const userCleanId = (user.identifier || '').replace(/\D/g, '');
    const dpaCleanNip = dpaNip.replace(/\D/g, '');
    if (userCleanId && dpaCleanNip && userCleanId === dpaCleanNip) {
      return true;
    }
  }

  // 1. Cek kecocokan Username dengan Dosen Pembimbing Aktif
  if (user.username && activeDosenNama) {
    const cleanUserUsername = user.username.toLowerCase().replace(/[^a-z0-9]/g, '');
    const cleanDpa = activeDosenNama.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (cleanUserUsername && cleanDpa && (cleanDpa.includes(cleanUserUsername) || cleanUserUsername.includes(cleanDpa))) {
      return true;
    }
  }

  // 2. Cek kecocokan Nama Lengkap Dosen dengan Dosen Pembimbing Aktif
  if (user.nama && activeDosenNama) {
    const normalize = (s: string) =>
      s
        .toLowerCase()
        .replace(/dr\.|dra\.|m\.si\.|s\.si\.|prof\.|ph\.d\.|m\.sc\.|s\.tp\.|m\.eng\.|ir\.|sc\.|m\.s\./gi, '')
        .replace(/[^a-z0-9\s]/gi, '')
        .trim();

    const userClean = normalize(user.nama);
    const dpaClean = normalize(activeDosenNama);

    if (userClean && dpaClean) {
      if (userClean === dpaClean || dpaClean.includes(userClean) || userClean.includes(dpaClean)) {
        return true;
      }
      const userTokens = userClean.split(/\s+/).filter((t) => t.length >= 3);
      if (userTokens.length > 0 && userTokens.some((t) => dpaClean.includes(t))) {
        return true;
      }
    }
  }

  return false;
};

export const checkIsMentorForStudent = (
  user: AuthUser | null | undefined,
  klkItem: PengajuanKLK | null | undefined,
  currentRole?: string
): boolean => {
  if (!user && !currentRole) return false;

  const roleToCheck = (currentRole || user?.role || '') as string;
  const isEksternalRole =
    roleToCheck === 'eksternal' ||
    (user?.role === 'eksternal' && !['dosen', 'mahasiswa', 'admin', 'super_admin'].includes(roleToCheck)) ||
    ((user?.role as any) === 'pembimbing_lapangan' && !['dosen', 'mahasiswa', 'admin', 'super_admin'].includes(roleToCheck)) ||
    ((user?.role as any) === 'mentor' && !['dosen', 'mahasiswa', 'admin', 'super_admin'].includes(roleToCheck)) ||
    ((user?.role as any) === 'pembimbing_industri' && !['dosen', 'mahasiswa', 'admin', 'super_admin'].includes(roleToCheck));

  // HANYA user eksternal (pembimbing lapangan) yang berhak melakukan checklist
  if (!isEksternalRole) {
    return false;
  }

  return true;
};


export const formatTanggalJamWib = (dateInput?: Date | string | number): string => {
  const d = dateInput ? new Date(dateInput) : new Date();
  const dateStr = d.toLocaleDateString('id-ID', {
    day: '2-digit',
    month: 'short',
    year: 'numeric'
  });
  const timeStr = d.toLocaleTimeString('id-ID', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  });
  return `${dateStr}, ${timeStr} WIB`;
};

export const getOrInitRiwayatKlk = (klk: PengajuanKLK): ItemRiwayatKLK[] => {
  const existing: ItemRiwayatKLK[] = klk.riwayatAktivitas && klk.riwayatAktivitas.length > 0
    ? [...klk.riwayatAktivitas]
    : [];

  const submitTime = klk.waktuSubmit || '14 Feb 2026, 09:30 WIB';
  const hasSubmitEntry = existing.some(
    (e) => e.aksi.toLowerCase().includes('formulir') || e.aksi.toLowerCase().includes('pendaftaran') || e.aksi.toLowerCase().includes('mengirim')
  );

  // 1. Riwayat Pengiriman Formulir oleh Mahasiswa (Tahap 1)
  if (!hasSubmitEntry) {
    existing.push({
      id: `rw-init-1-${klk.id}`,
      waktu: submitTime,
      timestamp: 1771061400000,
      role: 'Mahasiswa',
      namaAktor: klk.mahasiswaNama,
      aksi: 'Mengirim Formulir Usulan KLK',
      statusHasil: 'Diproses',
      catatan: `Mahasiswa ${klk.mahasiswaNama} (${klk.nim}) telah mengisi dan mengirimkan formulir pendaftaran KLK skema ${klk.skema} di ${klk.namaMitra} (${klk.sksDiakui} SKS). Usulan dialirkan ke Dosen Pembimbing Akademik (DPA) untuk evaluasi kurikulum dan CPL (Tahap 2).`,
      tahap: 'Tahap 1: Pengajuan Formulir Usulan KLK'
    });
  }

  // 2. Riwayat Verifikasi Dosen Pembimbing Akademik / DPA (Tahap 2)
  const hasDosenEntry = existing.some(
    (e) => e.role === 'Dosen' || e.tahap.toLowerCase().includes('dosen pa') || e.aksi.toLowerCase().includes('meneruskan ke admin') || e.aksi.toLowerCase().includes('meminta revisi usulan') || e.aksi.toLowerCase().includes('menolak usulan')
  );
  if (!hasDosenEntry) {
    if (klk.statusVerifikasiDosen === 'Disetujui Dosen' || klk.status === 'Disetujui' || klk.status === 'Disetujui / Sedang Berjalan' || klk.status === 'Selesai & Dinilai') {
      existing.push({
        id: `rw-init-2-${klk.id}`,
        waktu: klk.tanggalVerifikasiDosen ? `${klk.tanggalVerifikasiDosen}, 11:15 WIB` : '15 Feb 2026, 11:15 WIB',
        timestamp: 1771154100000,
        role: 'Dosen',
        namaAktor: klk.dosenVerifikatorKLK || klk.dpaNama || 'Dr. Dra. Hermin Sulistyarti, M.Si',
        aksi: 'Menyetujui & Meneruskan ke Admin TU',
        statusHasil: 'Disetujui Dosen',
        catatan: klk.catatanVerifikasiDosen || 'Topik riset/kerja kimia di instansi mitra telah selaras dengan kurikulum dan CPL Kimia UB. Usulan disetujui dan diteruskan ke Admin TU untuk validasi berkas serta penerbitan Surat Tugas.',
        tahap: 'Tahap 2: Evaluasi & Verifikasi Dosen PA'
      });
    } else if (klk.statusVerifikasiDosen === 'Perlu Revisi') {
      existing.push({
        id: `rw-init-2-${klk.id}`,
        waktu: klk.tanggalVerifikasiDosen ? `${klk.tanggalVerifikasiDosen}, 11:15 WIB` : '15 Feb 2026, 11:15 WIB',
        timestamp: 1771154100000,
        role: 'Dosen',
        namaAktor: klk.dosenVerifikatorKLK || klk.dpaNama || 'Dosen Pembimbing Akademik',
        aksi: 'Meminta Revisi Usulan',
        statusHasil: 'Perlu Revisi',
        catatan: klk.catatanVerifikasiDosen || 'Mohon sesuaikan rincian jadwal bimbingan dan metodologi analisis instrumen kimia pada usulan konversi SKS.',
        tahap: 'Tahap 2: Evaluasi & Verifikasi Dosen PA'
      });
    } else if (klk.statusVerifikasiDosen === 'Ditolak') {
      existing.push({
        id: `rw-init-2-${klk.id}`,
        waktu: klk.tanggalVerifikasiDosen ? `${klk.tanggalVerifikasiDosen}, 11:15 WIB` : '15 Feb 2026, 11:15 WIB',
        timestamp: 1771154100000,
        role: 'Dosen',
        namaAktor: klk.dosenVerifikatorKLK || klk.dpaNama || 'Dosen Pembimbing Akademik',
        aksi: 'Menolak Usulan',
        statusHasil: 'Ditolak',
        catatan: klk.catatanVerifikasiDosen || 'Rencana kegiatan tidak memenuhi bobot CPL minimum prodi Kimia.',
        tahap: 'Tahap 2: Evaluasi & Verifikasi Dosen PA'
      });
    }
  }

  // 3. Riwayat Verifikasi Super Admin & Admin TU (Tahap 3)
  const hasAdminEntry = existing.some(
    (e) => (e.role === 'Admin' || e.role === 'Super Admin' || e.tahap.toLowerCase().includes('admin tu') || e.tahap.toLowerCase().includes('verifikasi admin')) &&
      (e.aksi.toLowerCase().includes('surat') || e.aksi.toLowerCase().includes('menyetujui') || e.aksi.toLowerCase().includes('mengembalikan') || e.statusHasil === 'Disetujui' || e.statusHasil === 'Ditolak')
  );
  if (!hasAdminEntry) {
    if (klk.status === 'Disetujui' || klk.status === 'Disetujui / Sedang Berjalan' || klk.status === 'Selesai & Dinilai' || klk.nomorSuratTugas) {
      existing.push({
        id: `rw-init-3-${klk.id}`,
        waktu: '16 Feb 2026, 14:20 WIB',
        timestamp: 1771251600000,
        role: 'Admin',
        namaAktor: 'Admin TU SIKMA Kimia UB',
        aksi: 'Menyetujui & Menerbitkan Surat Pengantar & Surat Tugas',
        statusHasil: 'Disetujui',
        catatan: klk.catatanVerifikasi || `Seluruh berkas digital dinyatakan lengkap & absah setelah rekomendasi Dosen Pembimbing. Surat Pengantar Resmi ke Mitra (${klk.namaMitra}) dan Surat Tugas resmi nomor ${klk.nomorSuratTugas || '0814/UN10.F09/AK-KLK/2026'} telah diterbitkan. Dosen Pembimbing KLK ditetapkan: ${klk.dosenPembimbingKLK || klk.dpaNama || 'Dr. Dra. Hermin Sulistyarti, M.Si'}.`,
        tahap: 'Tahap 3: Verifikasi Admin TU & Penerbitan Surat Tugas'
      });
    } else if (klk.status === 'Ditolak' && klk.statusVerifikasiDosen !== 'Ditolak') {
      existing.push({
        id: `rw-init-3-${klk.id}`,
        waktu: '16 Feb 2026, 14:20 WIB',
        timestamp: 1771251600000,
        role: 'Admin',
        namaAktor: 'Admin TU SIKMA Kimia UB',
        aksi: 'Mengembalikan untuk Revisi',
        statusHasil: 'Ditolak',
        catatan: klk.catatanVerifikasi || 'Mohon lengkapi tanda tangan dan stempel instansi pada berkas usulan pendaftaran.',
        tahap: 'Tahap 3: Verifikasi Admin TU & Penerbitan Surat Tugas'
      });
    }
  }

  // 4. Riwayat Konfirmasi Pengiriman Surat Pengantar oleh Mahasiswa (Tahap 4)
  const hasKirimSuratEntry = existing.some(
    (e) => e.aksi.toLowerCase().includes('pengantar') || e.statusHasil === 'Surat Pengantar Dikirim'
  );
  if (klk.suratLamaranDikirim && !hasKirimSuratEntry) {
    existing.push({
      id: `rw-init-4-${klk.id}`,
      waktu: klk.waktuKirimSuratLamaran || '16 Feb 2026, 15:30 WIB',
      timestamp: 1771255800000,
      role: 'Mahasiswa',
      namaAktor: klk.mahasiswaNama,
      aksi: 'Mengonfirmasi Pengiriman Surat Pengantar ke Mitra',
      statusHasil: 'Surat Pengantar Dikirim',
      catatan: `Mahasiswa mengonfirmasi bahwa Surat Pengantar Resmi dari Departemen Kimia telah diserahkan/dikirimkan kepada pihak pimpinan instansi mitra ${klk.namaMitra}. Menunggu keputusan resmi jawaban mitra (Tahap 5).`,
      tahap: 'Tahap 4: Pengiriman Surat Pengantar ke Mitra'
    });
  }

  // 5. Riwayat Konfirmasi Respon / Jawaban Perusahaan Mitra (Tahap 5)
  const hasResponMitraEntry = existing.some(
    (e) => e.aksi.toLowerCase().includes('respon') || e.statusHasil === 'Diterima Mitra' || e.statusHasil === 'Ditolak Mitra'
  );
  if ((klk.statusResponMitra === 'Diterima' || klk.statusResponMitra === 'Ditolak') && !hasResponMitraEntry) {
    const dosenTujuan =
      klk.dosenPembimbingKLK && klk.dosenPembimbingKLK !== 'Belum Ditetapkan (Akan Ditetapkan Admin TU pada Tahap 3)'
        ? klk.dosenPembimbingKLK
        : (klk.dpaNama || 'Dosen Pembimbing KLK');
    existing.push({
      id: `rw-init-5-${klk.id}`,
      waktu: klk.waktuResponMitra || '17 Feb 2026, 10:00 WIB',
      timestamp: 1771322400000,
      role: 'Mahasiswa',
      namaAktor: klk.mahasiswaNama,
      aksi: klk.statusResponMitra === 'Diterima' ? 'Konfirmasi Diterima di Instansi Mitra' : 'Konfirmasi Ditolak oleh Instansi Mitra',
      statusHasil: klk.statusResponMitra === 'Diterima' ? 'Diterima Mitra' : 'Ditolak Mitra',
      catatan: klk.statusResponMitra === 'Diterima'
        ? `Mahasiswa mengonfirmasi resmi DITERIMA di instansi mitra ${klk.namaMitra}. Selanjutnya mahasiswa mengunggah dan mengirimkan berkas Surat Penerimaan resmi perusahaan kepada Dosen Pembimbing KLK (${dosenTujuan}) untuk diverifikasi (Tahap 6 & 7) sebelum akses Logbook dan Bimbingan dibuka.`
        : `Mahasiswa mengonfirmasi permohonan DITOLAK oleh instansi mitra ${klk.namaMitra}. Sesuai prosedur, mahasiswa mengulang dari awal pengisian formulir usulan KLK baru.`,
      tahap: 'Tahap 5: Konfirmasi Respon Jawaban Mitra'
    });
  }

  // 6. Riwayat Upload & Kirim Surat Resmi dari Perusahaan ke Dosen Pembimbing KLK (Tahap 6)
  const hasSuratBalasanEntry = existing.some(
    (e) => e.aksi.toLowerCase().includes('surat perusahaan') || e.aksi.toLowerCase().includes('surat balasan') || e.statusHasil === 'Surat Mitra Terkirim'
  );
  if (klk.dokumenSuratBalasanMitra && !hasSuratBalasanEntry) {
    const dosenTujuan =
      klk.dosenPembimbingKLK && klk.dosenPembimbingKLK !== 'Belum Ditetapkan (Akan Ditetapkan Admin TU pada Tahap 3)'
        ? klk.dosenPembimbingKLK
        : (klk.dpaNama || 'Dosen Pembimbing KLK');
    existing.push({
      id: `rw-init-6-${klk.id}`,
      waktu: klk.waktuKirimSuratBalasanMitra || '17 Feb 2026, 11:30 WIB',
      timestamp: 1771327800000,
      role: 'Mahasiswa',
      namaAktor: klk.mahasiswaNama,
      aksi: 'Mengunggah & Mengirimkan Surat Perusahaan ke Dosen Pembimbing KLK',
      statusHasil: 'Surat Mitra Terkirim',
      catatan: `Mahasiswa mengunggah dan mengirimkan Surat Penerimaan resmi dari instansi mitra ${klk.namaMitra} (No: ${klk.nomorSuratBalasanMitra || '082/HRD/2026'}) yang ditujukan kepada Dosen Pembimbing KLK (${dosenTujuan}). Menunggu evaluasi & persetujuan Dosen Pembimbing KLK (Tahap 7). Berkas: ${klk.dokumenSuratBalasanMitra}.`,
      tahap: 'Tahap 6: Unggah Surat Perusahaan ke Dosen Pembimbing KLK'
    });
  }

  // 7. Riwayat Pengecekan & Persetujuan Berkas Surat Perusahaan oleh Dosen Pembimbing KLK (Tahap 7)
  const hasDosenVerifikasiSuratEntry = existing.some(
    (e) => e.aksi.toLowerCase().includes('menyetujui berkas surat') || e.statusHasil === 'Surat Mitra Disetujui' || e.statusHasil === 'Perlu Perbaikan'
  );
  if (klk.suratMitraDisetujuiDosen && !hasDosenVerifikasiSuratEntry) {
    const activeDosen =
      klk.dosenPembimbingKLK && !klk.dosenPembimbingKLK.includes('Belum Ditetapkan')
        ? klk.dosenPembimbingKLK
        : (klk.dpaNama || 'Dr. Dra. Hermin Sulistyarti, M.Si');
    existing.push({
      id: `rw-init-7-${klk.id}`,
      waktu: klk.tanggalVerifikasiSuratMitraDosen || '17 Feb 2026, 12:45 WIB',
      timestamp: 1771332300000,
      role: 'Dosen',
      namaAktor: activeDosen,
      aksi: 'Menyetujui Berkas Surat Perusahaan & Membuka Akses Logbook & Bimbingan',
      statusHasil: 'Surat Mitra Disetujui',
      catatan: klk.catatanVerifikasiSuratMitraDosen || `Dosen Pembimbing KLK (${activeDosen}) telah memeriksa dan menyetujui berkas Surat Penerimaan resmi dari instansi mitra ${klk.namaMitra} (No: ${klk.nomorSuratBalasanMitra || '082/HRD/2026'}). Seluruh syarat pra-kegiatan terpenuhi, akses Logbook Mingguan dan Bimbingan KLK resmi dibuka aktif.`,
      tahap: 'Tahap 7: Persetujuan Berkas Surat Mitra oleh Dosen'
    });
  }

  // 8. Pelaksanaan KLK & Bimbingan Aktif (Tahap 8)
  const hasPelaksanaanEntry = existing.some(
    (e) => e.aksi.toLowerCase().includes('pelaksanaan') || e.statusHasil === 'Kegiatan Berjalan'
  );
  if (klk.suratMitraDisetujuiDosen && (klk.status === 'Disetujui / Sedang Berjalan' || klk.status === 'Selesai & Dinilai') && !hasPelaksanaanEntry) {
    existing.push({
      id: `rw-init-8-${klk.id}`,
      waktu: '17 Feb 2026, 13:00 WIB',
      timestamp: 1771333200000,
      role: 'Mahasiswa',
      namaAktor: klk.mahasiswaNama,
      aksi: 'Pelaksanaan KLK & Bimbingan Aktif',
      statusHasil: 'Kegiatan Berjalan',
      catatan: `Kegiatan praktik/magang kimia di instansi mitra ${klk.namaMitra} resmi berlangsung aktif. Mahasiswa wajib mengisi Presensi Harian, Logbook Mingguan secara berkala, dan melaksanakan Bimbingan Dosen minimal 6 sesi.`,
      tahap: 'Tahap 8: Pelaksanaan KLK & Bimbingan Aktif'
    });
  }

  // Normalisasi otomatis tahap pada item riwayat lama
  existing.forEach((item) => {
    const a = item.aksi.toLowerCase();
    if (a.includes('formulir') || a.includes('pendaftaran')) {
      item.tahap = 'Tahap 1: Pengajuan Formulir Usulan KLK';
    } else if (a.includes('meneruskan ke admin') || a.includes('revisi usulan') || a.includes('menolak usulan') || (item.role === 'Dosen' && (item.tahap === 'Verifikasi Dosen' || !item.tahap.includes('Tahap')))) {
      item.tahap = 'Tahap 2: Evaluasi & Verifikasi Dosen PA';
    } else if (a.includes('surat tugas') || a.includes('surat pengantar & surat tugas') || item.tahap === 'Verifikasi Admin') {
      item.tahap = 'Tahap 3: Verifikasi Admin TU & Penerbitan Surat Tugas';
    } else if (a.includes('pengantar') || a.includes('lamaran') || item.statusHasil === 'Surat Pengantar Dikirim') {
      item.tahap = 'Tahap 4: Pengiriman Surat Pengantar ke Mitra';
    } else if (a.includes('respon') || item.statusHasil === 'Diterima Mitra' || item.statusHasil === 'Ditolak Mitra') {
      item.tahap = 'Tahap 5: Konfirmasi Respon Jawaban Mitra';
    } else if (a.includes('surat perusahaan') || a.includes('surat balasan') || item.statusHasil === 'Surat Mitra Terkirim') {
      item.tahap = 'Tahap 6: Unggah Surat Perusahaan ke Dosen Pembimbing KLK';
    } else if (a.includes('menyetujui berkas surat') || item.statusHasil === 'Surat Mitra Disetujui' || item.statusHasil === 'Perlu Perbaikan') {
      item.tahap = 'Tahap 7: Persetujuan Berkas Surat Mitra oleh Dosen';
    } else if (a.includes('pelaksanaan') || item.statusHasil === 'Kegiatan Berjalan') {
      item.tahap = 'Tahap 8: Pelaksanaan KLK & Bimbingan Aktif';
    }
  });

  // Deduplikasi & Pengurutan (terbaru di atas)
  const seen = new Set<string>();
  const filtered = existing.filter((item) => {
    const key = `${item.role}-${item.aksi}-${item.statusHasil || ''}-${item.catatan || ''}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  return filtered.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
};

