  // Handler Aksi Button Status (Diproses - Kuning, Disetujui - Hijau, Ditolak - Merah) & Button Hapus (Merah Tua)
  const handleSetStatusBimbingan = (id: number, status: 'Diproses' | 'Disetujui' | 'Ditolak') => {
    setBimbinganSesiList((prev) =>
      prev.map((item) => (item.id === id ? { ...item, status } : item))
    );
    setBimbinganSavedSuccess(true);
    setBimbinganSavedMessage(`Status sesi bimbingan #${id} diubah menjadi "${status}"!`);
    setTimeout(() => setBimbinganSavedSuccess(false), 3500);
  };

  const handleDeleteBimbingan = (id: number) => {
    setBimbinganSesiList((prev) => prev.filter((item) => item.id !== id));
    setDeletingBimbinganId(null);
    setBimbinganSavedSuccess(true);
    setBimbinganSavedMessage(`Sesi bimbingan #${id} berhasil dihapus dari daftar.`);
    setTimeout(() => setBimbinganSavedSuccess(false), 3500);
  };

  // Handler Simpan Input Konsultasi Bimbingan Baru oleh Mahasiswa
  const handleSaveKartuBimbingan = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formKartuBimbingan.tanggalBimbingan || !formKartuBimbingan.detailBimbingan.trim() || !formKartuBimbingan.linkGoogleDrive.trim()) {
      return;
    }

    let formattedDate = formKartuBimbingan.tanggalBimbingan;
    try {
      const parts = formKartuBimbingan.tanggalBimbingan.split('-');
      if (parts.length === 3) {
        const year = parts[0];
        const monthIndex = parseInt(parts[1], 10) - 1;
        const day = parseInt(parts[2], 10);
        const months = [
          'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
          'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'
        ];
        if (monthIndex >= 0 && monthIndex < 12) {
          formattedDate = `${day < 10 ? '0' + day : day} ${months[monthIndex]} ${year}`;
        }
      }
    } catch {
      // fallback
    }

    const currentList = getOrInitSesiBimbingan(selectedKlk);
    const newId = currentList.length > 0 ? Math.max(...currentList.map(s => s.id)) + 1 : 1;
    const nowStr = new Date().toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' }) + ', ' + new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) + ' WIB';

    const judul = formKartuBimbingan.judulBimbingan.trim() || `Konsultasi & Diskusi Akademik Sesi Ke-${newId}`;

    const newEntry: SesiBimbinganItem = {
      id: newId,
      tanggal: formattedDate,
      waktuTanya: nowStr,
      pokokBahasan: `Sesi ${newId}: ${judul}`,
      pertanyaanMahasiswa: formKartuBimbingan.detailBimbingan.trim(),
      jawabanDosen: undefined,
      catatanDosen: undefined,
      linkGoogleDrive: formKartuBimbingan.linkGoogleDrive.trim(),
      parafDosen: false,
      status: 'Diproses'
    };

    if (selectedKlk) {
      handleSaveSesiBimbinganMahasiswa(selectedKlk.id, newEntry);
    } else {
      setBimbinganSesiList([newEntry, ...bimbinganSesiList]);
    }

    setBimbinganSavedSuccess(true);
    setBimbinganSavedMessage(`Sesi Bimbingan Ke-${newId} (${formattedDate}) berhasil dikirim ke Dosen Pembimbing KLK!`);
    setFormKartuBimbingan({
      tanggalBimbingan: new Date().toISOString().split('T')[0],
      judulBimbingan: '',
      detailBimbingan: '',
      linkGoogleDrive: formKartuBimbingan.linkGoogleDrive,
      status: 'Diproses'
    });

    setTimeout(() => {
      setBimbinganSavedSuccess(false);
    }, 4500);
  };

  // Handler Simpan Jawaban / Balasan Dosen Pembimbing untuk Sesi Bimbingan
  const handleSaveJawabanDosenSesi = (klkId: string, sesiId: number, jawabanText: string, status: 'Diproses' | 'Disetujui' | 'Ditolak') => {
    const targetKlk = klkList.find((k) => k.id === klkId);
    if (!targetKlk) return;

    // Otorisasi: Hanya Dosen Pembimbing KLK (atau Super Admin) yang berhak membalas / mengedit sesi bimbingan
    const isAuthorized = checkIsDosenPAForStudent(effectiveUser || currentUser, targetKlk, mahasiswaList);
    if (!isAuthorized) {
      const dosenName = targetKlk.dosenPembimbingKLK && !targetKlk.dosenPembimbingKLK.includes('Belum Ditetapkan') ? targetKlk.dosenPembimbingKLK : (targetKlk.dpaNama || 'Dosen Pembimbing');
      setBimbinganSavedMessage(`Otorisasi Terbatas: Hanya Dosen Pembimbing KLK dari mahasiswa yang bersangkutan (${dosenName}) yang mempunyai authorize untuk membalas/edit bimbingan.`);
      setBimbinganSavedSuccess(true);
      setTimeout(() => setBimbinganSavedSuccess(false), 4000);
      return;
    }

    const currentSesiList = getOrInitSesiBimbingan(targetKlk);
    const nowStr = new Date().toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' }) + ', ' + new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) + ' WIB';
    const dateToday = new Date().toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' });
    const effectiveDosenName = targetKlk.dosenPembimbingKLK && !targetKlk.dosenPembimbingKLK.includes('Belum Ditetapkan') ? targetKlk.dosenPembimbingKLK : (currentUser?.name || targetKlk.dpaNama || 'Dosen Pembimbing KLK');

    const updatedSesiList = currentSesiList.map((sesi) => {
      if (sesi.id === sesiId) {
        return {
          ...sesi,
          status,
          jawabanDosen: jawabanText.trim() || sesi.jawabanDosen || 'Bimbingan dan tanggapan disahkan oleh Dosen Pembimbing KLK.',
          catatanDosen: jawabanText.trim() || sesi.catatanDosen,
          waktuJawab: nowStr,
          parafDosen: status === 'Disetujui',
          tanggalParaf: status === 'Disetujui' ? (sesi.tanggalParaf || dateToday) : undefined,
          dosenNama: effectiveDosenName
        };
      }
      return sesi;
    });

    const updatedKlk: PengajuanKLK = {
      ...targetKlk,
      sesiBimbinganList: updatedSesiList
    };

    if (onUpdateKLK) {
      onUpdateKLK(updatedKlk);
    }
    setEditingSesiId(null);
    setJawabanInputText('');
    setBimbinganSavedSuccess(true);
    setBimbinganSavedMessage(`Tanggapan & balasan Dosen Pembimbing untuk Sesi #${sesiId} berhasil disimpan (Status: "${status}")!`);
    setTimeout(() => setBimbinganSavedSuccess(false), 3500);
  };

