        pdfDoc.setFont('helvetica', 'bold');
        pdfDoc.setFontSize(9);
        pdfDoc.setTextColor(22, 101, 52);
        pdfDoc.text('KEPUTUSAN: LULUS DENGAN PREDIKAT SANGAT MEMUASKAN', pageWidth / 2, y + 7.5, { align: 'center' });

