  // Handler: Simpan Absen Harian oleh Mahasiswa (Terhubung dengan Pembimbing Lapangan)
  const handleSaveAbsenHarian = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedKlk) return;

    const newAbsen: AbsenHarianKLK = {
      id: `absen-${Date.now()}`,
      tanggal: absenTanggal,
      hari: absenHari,
      jamMasuk: absenJamMasuk,
      jamPulang: absenJamPulang,
      aktivitasSingkat: absenAktivitas,
      statusKehadiran: absenStatus,
      keterangan: absenKeterangan || undefined,
      statusVerifikasiMentor: 'Menunggu Checklist'
    };

    const currentAbsens = getOrInitAbsenHarian(selectedKlk);
    const updatedKlk: PengajuanKLK = {
      ...selectedKlk,
      absenHarian: [newAbsen, ...currentAbsens]
    };

    if (onUpdateKLK) {
      onUpdateKLK(updatedKlk);
    }
    setAbsenSuccess(true);
    setAbsenAktivitas('');
    setAbsenKeterangan('');
    setTimeout(() => setAbsenSuccess(false), 3000);
  };

  // Handler: Checklist Absen khusus Pembimbing Lapangan (Mentor) Mahasiswa bersangkutan
  const handleChecklistAbsenMentor = (klkId: string, absenId: string, catatan?: string, toggleIfAlreadyVerified: boolean = false) => {
    const targetKlk = klkList.find((k) => k.id === klkId);
    if (!targetKlk) return;

    // Otorisasi: HANYA User Eksternal (Pembimbing Lapangan) yang berhak melakukan checklist
    const isAuthorized = checkIsMentorForStudent(effectiveUser || currentUser, targetKlk, currentRole);
    if (!isAuthorized) {
      const mentorName = targetKlk.mentorIndustri || 'Pembimbing Lapangan Mitra';
      setMentorToastMessage(`Otorisasi Ditolak: Hanya User Eksternal (Pembimbing Lapangan: ${mentorName}) yang berwenang melakukan checklist absensi.`);
      setMentorToastSuccess(false);
      setTimeout(() => setMentorToastSuccess(false), 4000);
      return;
    }

    const currentAbsens = getOrInitAbsenHarian(targetKlk);
    const nowStr = new Date().toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' }) + ', ' + new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) + ' WIB';
    const activeMentorNama = (effectiveUser?.nama || (currentUser as any)?.name) || targetKlk.mentorIndustri || 'Pembimbing Lapangan Mitra';
    
    let isVerifying = true;
    const updatedAbsens = currentAbsens.map((ab) => {
      if (ab.id === absenId) {
        const isVerified = ab.statusVerifikasiMentor === 'Terverifikasi' || ab.statusVerifikasiMentor === 'Terverifikasi Mentor';
        if (toggleIfAlreadyVerified && isVerified) {
          isVerifying = false;
          return {
            ...ab,
            statusVerifikasiMentor: 'Menunggu Checklist' as const,
            diverifikasiOleh: undefined,
            waktuVerifikasi: undefined,
            catatanMentor: catatan !== undefined ? catatan : ab.catatanMentor
          };
        } else {
          isVerifying = true;
          return {
            ...ab,
            statusVerifikasiMentor: 'Terverifikasi' as const,
            diverifikasiOleh: `Pembimbing Lapangan (${activeMentorNama})`,
            waktuVerifikasi: nowStr,
            catatanMentor: catatan !== undefined ? catatan : ab.catatanMentor
          };
        }
      }
      return ab;
    });

    const updatedKlk: PengajuanKLK = {
      ...targetKlk,
      absenHarian: updatedAbsens
    };

    if (onUpdateKLK) {
      onUpdateKLK(updatedKlk);
    }
    setMentorToastMessage(isVerifying ? 'Kehadiran dan laporan harian mahasiswa berhasil dichecklist terverifikasi oleh Pembimbing Lapangan!' : 'Status verifikasi absen dikembalikan ke Menunggu Checklist.');
    setMentorToastSuccess(true);
    setTimeout(() => setMentorToastSuccess(false), 3000);
  };

  // Handler: Checklist Absen Per-Minggu oleh Pembimbing Lapangan
  const handleChecklistWeekAbsenMentor = (klkId: string, weekNum: number) => {
    const targetKlk = klkList.find((k) => k.id === klkId);
    if (!targetKlk) return;

    // Otorisasi: HANYA User Eksternal (Pembimbing Lapangan) yang berhak melakukan checklist
    const isAuthorized = checkIsMentorForStudent(effectiveUser || currentUser, targetKlk, currentRole);
    if (!isAuthorized) {
      const mentorName = targetKlk.mentorIndustri || 'Pembimbing Lapangan Mitra';
      setMentorToastMessage(`Otorisasi Ditolak: Hanya User Eksternal (Pembimbing Lapangan: ${mentorName}) yang berwenang melakukan checklist absensi.`);
      setMentorToastSuccess(false);
      setTimeout(() => setMentorToastSuccess(false), 4000);
      return;
    }

    const currentAbsens = getOrInitAbsenHarian(targetKlk);
    const nowStr = new Date().toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' }) + ', ' + new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) + ' WIB';
    const activeMentorNama = (effectiveUser?.nama || (currentUser as any)?.name) || targetKlk.mentorIndustri || 'Pembimbing Lapangan Mitra';
    
    const updatedAbsens = currentAbsens.map((ab, idx) => {
      const itemWeek = ab.mingguKe || (Math.floor(idx / 5) + 1);
      if (itemWeek === weekNum) {
        return {
          ...ab,
          statusVerifikasiMentor: 'Terverifikasi' as const,
          diverifikasiOleh: `Pembimbing Lapangan (${activeMentorNama})`,
          waktuVerifikasi: ab.waktuVerifikasi || nowStr
        };
      }
      return ab;
    });

    const updatedKlk: PengajuanKLK = {
      ...targetKlk,
      absenHarian: updatedAbsens
    };

    if (onUpdateKLK) {
      onUpdateKLK(updatedKlk);
    }
    setMentorToastMessage(`Seluruh entri absen harian Minggu Ke-${weekNum} berhasil dichecklist terverifikasi oleh Pembimbing Lapangan!`);
    setMentorToastSuccess(true);
    setTimeout(() => setMentorToastSuccess(false), 3500);
  };

