                    {/* BANNER MENUNGGU PERSETUJUAN ADMIN SEBELUM KONFIRMASI SURAT PENGANTAR DIAKTIFKAN */}
                    {(latestSubmittedKlk.statusVerifikasiDosen === 'Disetujui Dosen' || latestSubmittedKlk.statusVerifikasiDosen === 'Disetujui') &&
                      latestSubmittedKlk.status !== 'Disetujui' &&
                      latestSubmittedKlk.status !== 'Disetujui / Sedang Berjalan' &&
                      latestSubmittedKlk.status !== 'Selesai & Dinilai' && (
                        <div className="p-4 bg-blue-50/80 border-2 border-blue-300 rounded-xl space-y-2 shadow-2xs">
                          <div className="flex items-center gap-2 font-extrabold text-blue-950 text-xs sm:text-sm">
                            <Clock className="w-4 h-4 text-blue-600 shrink-0 animate-spin" />
                            <span>Menunggu Persetujuan Admin TU untuk Penerbitan Surat Pengantar ke Mitra</span>
                          </div>
                          <p className="text-[11px] text-blue-900 leading-relaxed">
                            Usulan dan konversi SKS telah <strong className="text-emerald-700">disetujui oleh Dosen Pembimbing Akademik (Dosen PA)</strong>. Saat ini berkas usulan sedang dalam antrean verifikasi administratif dan penerbitan Surat Tugas / Surat Pengantar Resmi oleh Admin TU. Modul <strong>Konfirmasi Pengiriman Surat Pengantar &amp; Hasil Respon Instansi Mitra</strong> akan otomatis muncul setelah pengajuan disetujui oleh Admin TU.
                          </p>
                        </div>
                      )}

                    {/* MODUL KONFIRMASI PENGIRIMAN SURAT PENGANTAR & RESPON MITRA/INSTANSI (Hanya muncul ketika sudah disetujui Admin) */}
